import { email, attio, kg } from adapters
import { dealflow_inbox, acme_main, native_knowledge } from credentials

inbox = email(credentials: dealflow_inbox)
crm   = attio(credentials: acme_main)
graph = kg(credentials: native_knowledge)
movement main(msg: <inbox-[:message]->>) {
  org = write crm-[:companies]-> { unique by (`Name`), Name: "Acme", Domains: ["acme.com"] }
  n = COUNT(org-[:@previous]->)
  write crm-[:notes]-> { title: IF org.created THEN "y" ELSE "n" END }
  ex = match crm-[:companies]-> { unique by (`Name`), Name: "Acme" }
  if ex != null { k = COUNT(ex-[:@old]->) }
  write org { Name: "Acme Ltd" }
  org2 = write org { Name: "Acme Ltd" }
  d = org.Domains
}
listen to inbox fire main

